<template>
<div class="vv-login-container"><el-card><template #header>客户管理</template>
<el-form inline @submit.prevent="search"><el-form-item label="客户"><el-input v-model="query.keyword" placeholder="编号 / 名称" clearable @keyup.enter="search" /></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable style="width:120px"><el-option label="启用" :value="1"/><el-option label="停用" :value="0"/></el-select></el-form-item><el-button @click="search">查询</el-button><el-button type="primary" @click="openEdit()">新增客户</el-button></el-form>
<el-table v-loading="loading" :data="list" row-key="id"><el-table-column prop="customerNo" label="客户编号" min-width="120"/><el-table-column prop="customerName" label="客户名称" min-width="140"/><el-table-column label="默认客户" width="100"><template #default="{row}"><el-tag v-if="row.isDefault" type="success">默认</el-tag><span v-else>—</span></template></el-table-column><el-table-column label="VV 账号" min-width="120"><template #default="{row}">{{ row.account || '未配置' }}</template></el-table-column><el-table-column label="登录状态" min-width="120"><template #default="{row}"><el-tag :type="row.authStatus==='VALID'?'success':row.authStatus==='CONFLICT'?'danger':'info'">{{ statusText(row.authStatus) }}</el-tag><div>{{ row.message }}</div></template></el-table-column><el-table-column prop="checkedAt" label="最近检测" min-width="160"/><el-table-column prop="groupCount" label="绑定群数" width="90"/><el-table-column label="启用状态" width="90"><template #default="{row}">{{ row.status===1?'启用':'停用' }}</template></el-table-column><el-table-column label="操作" min-width="300"><template #default="{row}"><el-button link type="primary" @click="openEdit(row)">编辑</el-button><el-button v-if="!row.isDefault" v-auth="'api/v1/system/vvAuth/customerDefault'" link :disabled="row.status!==1" :loading="rowBusy[row.id]" @click="makeDefault(row)">设为默认</el-button><el-button link type="primary" :disabled="row.status!==1||!row.hasVVAccount" @click="openLogin(row)">VV 登录</el-button><el-button link :disabled="!row.hasVVAccount" :loading="rowBusy[row.id]" @click="refreshStatus(row)">刷新状态</el-button><el-button link :loading="rowBusy[row.id]" @click="toggleStatus(row)">{{ row.status===1?'停用':'启用' }}</el-button></template></el-table-column></el-table>
<el-pagination v-model:current-page="query.pageNum" v-model:page-size="query.pageSize" :total="total" layout="total, sizes, prev, pager, next" @current-change="loadList" @size-change="search"/></el-card>
<el-dialog v-model="editVisible" :title="editForm.id?'编辑客户':'新增客户'" width="560px" destroy-on-close @closed="editForm.password=''" :close-on-click-modal="!saving"><el-form label-width="100px"><el-form-item v-if="editForm.id" label="客户编号"><el-input :model-value="editNo" disabled/></el-form-item><el-form-item label="客户名称" required><el-input v-model="editForm.customerName"/></el-form-item><el-form-item label="VV 账号" :required="!!editAccount"><el-input v-model="editForm.account" autocomplete="off" placeholder="可留空，后续再配置"/></el-form-item><el-form-item label="密码" :required="!!editForm.account&&(!editAccount||editForm.account!==editAccount)"><el-input v-model="editForm.password" type="password" autocomplete="new-password" :placeholder="editAccount?'留空保留已有密码':'配置 VV 账号时填写密码'"/></el-form-item><el-form-item label="状态"><el-switch v-model="editForm.status" :active-value="1" :inactive-value="0"/></el-form-item><el-form-item label="客户操作员"><el-input v-model="operatorText" type="textarea" :rows="4" placeholder="每行一个 wxid"/></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="editVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
<el-dialog v-model="loginVisible" title="VV 登录" width="480px" destroy-on-close @close="closeLogin"><p>{{ loginCustomer?.customerNo }} · {{ loginCustomer?.customerName }} · {{ loginCustomer?.account }}</p><el-button :loading="captchaLoading" :disabled="loggingIn" @click="loadCaptcha">{{ captcha.sessionId?'刷新验证码':'获取验证码' }}</el-button><div v-if="captcha.sessionId" class="captcha-row"><img :src="captcha.imageDataUrl" alt="VV 验证码"/><el-input v-model="verifyCode" maxlength="8" placeholder="输入验证码" @keyup.enter="login"/></div><template #footer><el-button @click="loginVisible=false">关闭</el-button><el-button type="primary" :loading="loggingIn" :disabled="!captcha.sessionId||captchaLoading" @click="login">登录</el-button></template></el-dialog>
</div>
</template>
<script setup lang="ts">
import { onMounted,onBeforeUnmount,reactive,ref } from 'vue';
import { ElMessage } from 'element-plus';
import {getVVCustomers,saveVVCustomer,setVVCustomerStatus,setDefaultVVCustomer,getVVCustomerCaptcha,loginVVCustomer,getVVCustomerStatus,type VVCustomer,type VVCustomerSave} from '/@/api/system/vvCustomer';
defineOptions({name:'flowDataLogin'});
const query=reactive({keyword:'',status:'' as number|'',pageNum:1,pageSize:10});const list=ref<VVCustomer[]>([]);const total=ref(0);const loading=ref(false);let listGeneration=0;
const rowBusy=reactive<Record<number,boolean>>({});const rowGeneration:Record<number,number>={};
const statusText=(status:string)=>({UNCONFIGURED:'未配置VV账号',VALID:'已登录',EXPIRED:'登录已过期',MISSING:'未登录',UNKNOWN:'检测失败',CONFLICT:'家族身份冲突'} as Record<string,string>)[status]||'未知';
const loadList=async()=>{const generation=++listGeneration;loading.value=true;try{const res:any=await getVVCustomers(query);if(generation!==listGeneration)return;list.value=res.data.list??[];total.value=res.data.total??0;}finally{if(generation===listGeneration)loading.value=false;}};
const search=()=>{query.pageNum=1;return loadList();};
const updateRow=(id:number,data:Partial<VVCustomer>)=>{const row=list.value.find(item=>item.id===id);if(row)Object.assign(row,data);};
const refreshStatus=async(row:VVCustomer)=>{if(rowBusy[row.id])return;const id=row.id;const generation=rowGeneration[id]=(rowGeneration[id]||0)+1;rowBusy[id]=true;try{const res:any=await getVVCustomerStatus(id);if(rowGeneration[id]===generation)updateRow(id,{authStatus:res.data.status,checkedAt:res.data.checkedAt,message:res.data.message});if(res.data.status==='CONFLICT')await loadList();}catch(error:any){if(rowGeneration[id]===generation)updateRow(id,{message:error?.message||'状态检测失败'});}finally{if(rowGeneration[id]===generation)rowBusy[id]=false;}};
const toggleStatus=async(row:VVCustomer)=>{if(rowBusy[row.id])return;const id=row.id;rowBusy[id]=true;try{const res:any=await setVVCustomerStatus({id,status:row.status===1?0:1,version:row.version});updateRow(id,res.data);}finally{rowBusy[id]=false;}};
const makeDefault=async(row:VVCustomer)=>{if(rowBusy[row.id])return;rowBusy[row.id]=true;try{await setDefaultVVCustomer({id:row.id,version:row.version});ElMessage.success('默认客户已更新');await loadList();}finally{rowBusy[row.id]=false;}};
const emptyForm=():VVCustomerSave=>({id:0,customerName:'',account:'',password:'',status:1,version:0,operatorWxids:[]});const editForm=reactive(emptyForm());const editVisible=ref(false);const editNo=ref('');const editAccount=ref('');const operatorText=ref('');const saving=ref(false);
const openEdit=(row?:VVCustomer)=>{if(saving.value)return;Object.assign(editForm,emptyForm(),row?{id:row.id,customerName:row.customerName,account:row.account,status:row.status,version:row.version}:{});editNo.value=row?.customerNo||'';editAccount.value=row?.account||'';operatorText.value=(row?.operatorWxids||[]).join('\n');editVisible.value=true;};
const save=async()=>{if(saving.value)return;if(!editForm.customerName.trim()){ElMessage.warning('请填写客户名称');return;}if(editAccount.value&&!editForm.account.trim()){ElMessage.warning('已配置VV账号不能清空');return;}if((!editForm.account.trim()&&editForm.password)||(editForm.account.trim()&&(!editAccount.value||editForm.account.trim()!==editAccount.value)&&!editForm.password)){ElMessage.warning('首次配置或更换VV账号必须同时填写账号和密码');return;}saving.value=true;try{await saveVVCustomer({...editForm,customerName:editForm.customerName.trim(),account:editForm.account.trim(),operatorWxids:[...new Set(operatorText.value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean))]});editVisible.value=false;editForm.password='';ElMessage.success('客户已保存');await loadList();}finally{saving.value=false;}};
const loginVisible=ref(false);const loginCustomer=ref<VVCustomer>();const captcha=reactive({sessionId:'',imageDataUrl:''});const verifyCode=ref('');const captchaLoading=ref(false);const loggingIn=ref(false);
// Closed or replaced dialogs must not receive a previous customer's responses.
let loginGeneration=0;
const closeLogin=()=>{++loginGeneration;loginCustomer.value=undefined;Object.assign(captcha,{sessionId:'',imageDataUrl:''});verifyCode.value='';captchaLoading.value=false;loggingIn.value=false;};
const openLogin=(row:VVCustomer)=>{closeLogin();loginCustomer.value={...row};loginVisible.value=true;};
const loadCaptcha=async()=>{const id=loginCustomer.value?.id;if(!id)return;const generation=++loginGeneration;captchaLoading.value=true;Object.assign(captcha,{sessionId:'',imageDataUrl:''});verifyCode.value='';try{const res:any=await getVVCustomerCaptcha(id);if(generation===loginGeneration&&loginCustomer.value?.id===id)Object.assign(captcha,res.data);}finally{if(generation===loginGeneration)captchaLoading.value=false;}};
const login=async()=>{const id=loginCustomer.value?.id;if(!id||!captcha.sessionId||!verifyCode.value.trim()||loggingIn.value||captchaLoading.value)return;const generation=loginGeneration;loggingIn.value=true;try{const res:any=await loginVVCustomer({customerId:id,sessionId:captcha.sessionId,verifyCode:verifyCode.value.trim()});if(generation!==loginGeneration||loginCustomer.value?.id!==id)return;updateRow(id,res.data);loginVisible.value=false;closeLogin();ElMessage.success('VV 登录成功');}finally{if(generation===loginGeneration)loggingIn.value=false;}};
onMounted(loadList);onBeforeUnmount(()=>{++listGeneration;closeLogin();Object.keys(rowGeneration).forEach(id=>rowGeneration[Number(id)]++);});
</script>
<style scoped>.vv-login-container :deep(.el-card){min-height:0}.captcha-row{display:flex;align-items:center;gap:12px;margin-top:16px}.captcha-row img{width:120px;height:40px;object-fit:contain}.el-pagination{margin-top:16px}</style>
